#include "transient_detector.h"

#include <algorithm>
#include <cmath>
#include <limits>

namespace phasegrid {

TransientDetector::TransientDetector() { reset(Config{}); }
TransientDetector::TransientDetector(const Config& config) { reset(config); }

bool TransientDetector::reject(const char* error) {
    m_error = error;
    return false;
}

bool TransientDetector::reset(const Config& config) {
    m_valid = false;
    m_finalized = false;
    m_transients.clear();
    m_error.clear();
    if (!std::isfinite(config.sample_rate) || config.sample_rate < 1000 ||
            config.sample_rate > 384000 || (config.channels != 1 && config.channels != 2) ||
            !std::isfinite(config.window_seconds) || config.window_seconds < 0.001 ||
            config.window_seconds > 0.1 || !std::isfinite(config.hop_seconds) ||
            config.hop_seconds <= 0 || config.hop_seconds > config.window_seconds ||
            !std::isfinite(config.threshold) || config.threshold <= 0 ||
            !std::isfinite(config.refractory_seconds) || config.refractory_seconds < 0 ||
            config.refractory_seconds > 1) {
        return reject("invalid transient-detector configuration");
    }
    m_config = config;
    m_window_frames = static_cast<std::size_t>(std::llround(config.window_seconds * config.sample_rate));
    m_hop_frames = std::max(std::size_t(1),
            static_cast<std::size_t>(std::llround(config.hop_seconds * config.sample_rate)));
    m_filter_alpha = 1 - std::exp(-2 * std::acos(-1.0) *
            std::min(180.0, config.sample_rate * 0.2) / config.sample_rate);
    m_adaptation_alpha = 1 - std::exp(-static_cast<double>(m_hop_frames) /
            (0.5 * config.sample_rate));
    m_energy_ring.assign(m_window_frames, 0);
    m_bass_ring.assign(m_window_frames, 0);
    m_cursor = 0;
    m_frames = m_last_window_frame = m_last_onset_frame = 0;
    m_have_onset = false;
    m_energy = m_bass_energy = m_previous_rms = m_novelty_average = 0;
    m_before_previous = {};
    m_previous = {};
    m_lowpass_first = {};
    m_lowpass_second = {};
    m_valid = true;
    return true;
}

bool TransientDetector::process(const float* interleaved, std::size_t sample_count) {
    if (!m_valid) return reject("detector has no valid configuration");
    if (m_finalized) return reject("input after finalization");
    if (sample_count % m_config.channels) return reject("input ends in an incomplete audio frame");
    if (sample_count && !interleaved) return reject("null PCM input");
    if (sample_count / m_config.channels > std::numeric_limits<std::uint64_t>::max() - m_frames) {
        return reject("audio frame counter overflow");
    }
    for (std::size_t sample = 0; sample < sample_count; ++sample) {
        if (!std::isfinite(interleaved[sample])) return reject("non-finite PCM input");
    }
    m_error.clear();
    for (std::size_t sample = 0; sample < sample_count; sample += m_config.channels) {
        double full = 0;
        double bass = 0;
        for (std::size_t channel = 0; channel < m_config.channels; ++channel) {
            const double value = interleaved[sample + channel];
            full += value * value;
            m_lowpass_first[channel] += m_filter_alpha * (value - m_lowpass_first[channel]);
            m_lowpass_second[channel] += m_filter_alpha *
                    (m_lowpass_first[channel] - m_lowpass_second[channel]);
            bass += m_lowpass_second[channel] * m_lowpass_second[channel];
        }
        full /= m_config.channels;
        bass /= m_config.channels;
        m_energy += full - m_energy_ring[m_cursor];
        m_bass_energy += bass - m_bass_ring[m_cursor];
        m_energy_ring[m_cursor] = full;
        m_bass_ring[m_cursor] = bass;
        m_cursor = (m_cursor + 1) % m_window_frames;
        ++m_frames;
        if (m_frames >= m_window_frames && m_frames % m_hop_frames == 0) evaluate_window();
    }
    return true;
}

void TransientDetector::evaluate_window() {
    const double rms = std::sqrt(std::max(0.0, m_energy / m_window_frames));
    const double bass_rms = std::sqrt(std::max(0.0, m_bass_energy / m_window_frames));
    const double novelty = std::max(0.0, rms - m_previous_rms);
    const double threshold = std::max(1e-5, m_config.threshold * m_novelty_average);
    observe({novelty, threshold, rms, bass_rms, m_frames});
    m_previous_rms = rms;
    m_novelty_average += m_adaptation_alpha * (novelty - m_novelty_average);
    m_last_window_frame = m_frames;
}

void TransientDetector::observe(const Observation& observation) {
    if (m_previous.novelty > m_before_previous.novelty &&
            m_previous.novelty >= observation.novelty &&
            m_previous.novelty > m_previous.threshold &&
            (!m_have_onset || static_cast<double>(m_previous.end_frame - m_last_onset_frame) >=
                    m_config.refractory_seconds * m_config.sample_rate)) {
        const double frame = std::max(0.0,
                static_cast<double>(m_previous.end_frame) - 0.5 * m_window_frames);
        const double bass_fraction = std::clamp(m_previous.bass_rms /
                std::max(1e-12, m_previous.rms), 0.0, 1.0);
        m_transients.push_back({frame / m_config.sample_rate,
                m_previous.novelty, m_previous.novelty * bass_fraction});
        m_last_onset_frame = m_previous.end_frame;
        m_have_onset = true;
    }
    m_before_previous = m_previous;
    m_previous = observation;
}

bool TransientDetector::finalize() {
    if (!m_valid) return reject("detector has no valid configuration");
    m_error.clear();
    if (m_finalized) return true;
    if (m_frames >= m_window_frames && m_last_window_frame != m_frames) evaluate_window();
    observe({0, 0, 0, 0, m_frames});
    m_finalized = true;
    return true;
}

} // namespace phasegrid
